import React, { useState, useRef } from 'react';

const AudioUploader = ({ onAudioSelect, onAudioRemove, uploadedAudios }) => {
  const [dragActive, setDragActive] = useState(false);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef(null);

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const handleFileInput = (e) => {
    if (e.target.files && e.target.files[0]) {
      handleFiles(e.target.files);
    }
  };

  const handleFiles = async (files) => {
    setUploading(true);

    try {
      for (let file of files) {
        if (file.type.startsWith('audio/')) {
          const audioUrl = URL.createObjectURL(file);
          const audioData = {
            id: Date.now() + Math.random(),
            name: file.name.replace(/\.[^/.]+$/, ""), // Remove file extension
            url: audioUrl,
            file: file,
            size: file.size,
            type: file.type,
            duration: 0
          };

          // Get audio duration
          try {
            const audio = new Audio(audioUrl);
            await new Promise((resolve) => {
              audio.addEventListener('loadedmetadata', () => {
                audioData.duration = audio.duration;
                resolve();
              });
              audio.addEventListener('error', resolve);
            });
          } catch (err) {
            console.warn('Could not get duration for:', file.name);
          }

          onAudioSelect(audioData);
        }
      }
    } catch (err) {
      console.error('Error processing files:', err);
    } finally {
      setUploading(false);
    }
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const formatDuration = (seconds) => {
    if (!seconds || isNaN(seconds)) return '--:--';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const openFileDialog = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="card mb-6">
      <h2 className="text-xl font-semibold text-white mb-4 text-center">
        Upload Your Own Audio
      </h2>

      {/* Upload Area */}
      <div
        className={`border-2 border-dashed rounded-lg p-8 text-center transition-colors ${
          dragActive 
            ? 'border-primary-500 bg-primary-500/10' 
            : 'border-gray-600 hover:border-gray-500'
        }`}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
      >
        <div className="space-y-4">
          <div className="text-6xl">🎵</div>
          <div>
            <p className="text-lg text-white mb-2">
              {uploading ? 'Processing audio files...' : 'Drop your audio files here'}
            </p>
            <p className="text-sm text-gray-400 mb-4">
              or click to browse files
            </p>
            <button
              onClick={openFileDialog}
              disabled={uploading}
              className="btn-primary"
            >
              {uploading ? 'Processing...' : 'Choose Audio Files'}
            </button>
          </div>
          <p className="text-xs text-gray-500">
            Supported formats: MP3, WAV, AAC, OGG, FLAC
          </p>
        </div>
      </div>

      {/* Hidden File Input */}
      <input
        ref={fileInputRef}
        type="file"
        multiple
        accept="audio/*"
        onChange={handleFileInput}
        className="hidden"
      />

      {/* Uploaded Audio List */}
      {uploadedAudios.length > 0 && (
        <div className="mt-6">
          <h3 className="text-lg font-medium text-white mb-3">
            Your Audio Library ({uploadedAudios.length})
          </h3>
          <div className="space-y-2 max-h-64 overflow-y-auto">
            {uploadedAudios.map((audio) => (
              <div
                key={audio.id}
                className="flex items-center justify-between p-3 bg-gray-700/50 rounded-lg border border-gray-600"
              >
                <div className="flex-1 min-w-0">
                  <p className="text-white font-medium truncate">{audio.name}</p>
                  <div className="flex items-center space-x-4 text-sm text-gray-400">
                    <span>{formatFileSize(audio.size)}</span>
                    <span>{formatDuration(audio.duration)}</span>
                    <span className="text-xs">{audio.type.split('/')[1].toUpperCase()}</span>
                  </div>
                </div>
                <div className="flex items-center space-x-2">
                  <button
                    onClick={() => onAudioSelect(audio)}
                    className="px-3 py-1 bg-primary-600 hover:bg-primary-700 text-white text-sm rounded transition-colors"
                  >
                    Play
                  </button>
                  <button
                    onClick={() => onAudioRemove(audio.id)}
                    className="px-3 py-1 bg-red-600 hover:bg-red-700 text-white text-sm rounded transition-colors"
                  >
                    Remove
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Tips */}
      <div className="mt-4 text-center text-sm text-gray-400">
        <p className="text-green-400 mb-2">✅ Your audio files stay in your browser - they're not uploaded to any server</p>
        <p>Perfect for personal music, podcasts, or any audio content you want to stream</p>
      </div>
    </div>
  );
};

export default AudioUploader;
